class PersonRequest:
    _VALID_SEXES = ["Man", "Woman", "UGM"]
    _MAX_NAME_LENGTH = 33
    _PHONE_LENGTH = 11

    def __init__(self, name: str, sex: str, phoneNumber: str):
        self._name = self._validate_name(name)
        self._sex = self._validate_sex(sex)
        self._phoneNumber = self._validate_phoneNumber(phoneNumber)

    @property
    def name(self) -> str:
        return self._name

    @name.setter
    def name(self, name: str) -> None:
        self._name = self._validate_name(name)

    @property
    def sex(self) -> str:
        return self._sex

    @sex.setter
    def sex(self, sex: str) -> None:
        self._sex = self._validate_sex(sex)

    @property
    def phoneNumber(self) -> str:
        return self._phoneNumber

    @phoneNumber.setter
    def phoneNumber(self, phoneNumber: str) -> None:
        self._phoneNumber = self._validate_phoneNumber(phoneNumber)

    def _validate_name(self, name: str) -> str:
        if not name:
            return None
        if len(name) > self._MAX_NAME_LENGTH:
            return None
        return name

    def _validate_sex(self, sex: str) -> str:
        if sex not in self._VALID_SEXES:
            return None
        return sex

    def _validate_phoneNumber(self, phoneNumber: str) -> str:
        if not phoneNumber:
            return None
        if len(phoneNumber) != self._PHONE_LENGTH or not phoneNumber.isdigit():
            return None
        return phoneNumber
